import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch O: the same cases, played out another way.
extension StoryVariants {
    static let variantsO: [CaseTemplate] = [keyboardSabotageV1, nurseDiversionV1, beachTripV1, beachHouseV1, horseStarvationV1, gasStationKidnappingV1, tractorDWIV1, halloweenPorchV1, groceryFallV1, jailSmugglingV1, daycareCamerasV1, feedStoreFireV1, deerCampFelonV1, catfishMeetupV1, wrongWayDriverV1, boatLandingV1, deedForgeryV1, informantBuyV1, parentsMansionV1, copperTheftV1, footballRiotV1, busStopPurseV1, affluenzaCrashV1, brakeCheckShootingV1, sheriffEvidenceMoneyV1, rentalCarPillsV1, missingToddlerV1, churchArsonistV1, sovereignStopV1, hiddenTrackerV1, cyclistHitAndRunV1, hazingDeathV1, stolenValorV1, fentanylStashV1, neighborStalkingV1, chopShopV1, moonshineExplosionV1, pharmacyRobberyV1]

    static let keyboardSabotageV1 = SmallCases.make(
        key: "story.keyboardSabotage",
        category: .cyber,
        headlines: ["Ex-Employee's Login Used to Erase Company Server at Midnight", "Backup Drive Left Empty After Firing"],
        law: "damagingComputers",
        threshold: 6,
        spec: "Willfully damaged the computers of {V}, a company, by deleting its data without authority, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was let go from {V}'s office on {DATE}. At midnight the company's shared drive and backups were erased through a remote login that still carried {D}'s credentials. Rebuilding the files cost $18,000. {DL} says the password was written on a sticky note anyone could use.",
        state: [E(.digital, 3, "Remote Login Log", "The erase command came from {D}'s old username at 12:04 a.m."), E(.digital, 3, "Router Record", "The login came from an address assigned to {D}'s home."), E(.document, 1, "Termination Notice", "Access was supposed to end the day of the firing.")],
        defense: [E(.statement, 1, "Sticky Note", "{DL} says the password was posted on the break room wall.")],
        role: "Company owner",
        exam: [.direct("What was lost at your company?", "\"Every client file and every backup. Years of work were erased from the shared drive in a single overnight command.\""), .direct("When did it happen?", "\"At 12:04 a.m., the night of the day I let {D} go. The remote login log shows the erase command at that moment.\""), .direct("Whose login did it?", "\"{D.his} old username, from the log. The command came in through a remote login that still carried {D.his} credentials.\""), .direct("Where did the login come from?", "\"An address the router record shows was assigned to {D.his} home. It matches the home connection on file.\""), .direct("Was {D}'s access supposed to end?", "\"It should have been that day. The termination notice said access ended on the day of the firing, and IT had not yet done it.\""), .direct("What did it cost you?", "\"$18,000 to rebuild the files, plus days of lost work and calls to clients explaining what had happened.\""), .cross("Who else knew the password?", "\"Several people. It was written on a sticky note near the shared workstations, and anyone in the office could read it.\""), .cross("Did you tell IT to shut off the defendant's access?", "\"I assumed it would be done. I did not follow up that afternoon, and I regret that.\""), .cross("Can you say who was at the keyboard?", "\"No. The log shows a username and an address, not the person who typed.\""), .cross("Did the defendant threaten you when let go?", "\"No. {D.He} was upset but not threatening. {D.He} packed up and left quietly.\""), .cross("Was the defendant good at the job?", "\"Yes. {D.He} was reliable and thorough, and the firing was a cost decision.\"")],
        theory: ("{D} wiped the company's files after the firing.", "Anyone could have used the old login."),
        allocution: "\"I thought nobody would be hurt. I was wrong.\"",
        truths: ("{DL} had asked about the backup schedule the week before.", "Two coworkers still used {D}'s login for months."),
        defendant: [.direct("Did you erase the drive?", "\"No. I did not erase anything, and I would never destroy files that I helped build for the company.\""), .direct("Why was your login used?", "\"It was never turned off. The company left my access live after I was let go, and anyone could have used it.\""), .direct("Who knew your password?", "\"Several people. It was on a sticky note by the shared computers, because the office never changed it.\""), .direct("The address was yours, wasn't it?", "\"My phone was on that router, yes. That connects my home network, not a particular person at a keyboard.\""), .direct("Where were you at midnight?", "\"At home, asleep. I had been let go that day, and I was too tired and upset to do anything but sleep.\""), .direct("What do you want your former employer to know?", "\"I am sorry for the loss. I did not do this, and I hope you find who did.\""), .cross("The erase command came from your username, didn't it?", "\"From my old username, yes, but I did not type it.\""), .cross("The login came from an address assigned to your home, didn't it?", "\"Yes, that is my router. I was home, and I did not use it that way.\""), .cross("You were upset about being let go, weren't you?", "\"Of course. I was hurt, but being hurt is not the same as destroying files.\""), .cross("You knew how the backups worked, didn't you?", "\"I did my job, so I knew. Several coworkers knew too.\""), .cross("Nobody can say you were asleep at midnight, can they?", "\"No. I live alone. I wish I could prove it.\"")],
        openings: ("{D} was let go on a Wednesday. At midnight the company's shared drive and backups were erased through a remote login that still carried {D}'s credentials, from an address tied to {D}'s home, and rebuilding the files cost $18,000.", "{D}'s password sat on a sticky note anyone could read, and IT never shut off the login. A username in a log is not a person at a keyboard."),
        closings: ("A fired employee, a login at 12:04 a.m., a router tied to {D}'s home, and every backup gone. Who else had a reason and the access?", "A sticky note, a login that never closed, and a log that cannot name a person. The State must prove {D} typed that command."),
        timeline: [(-3, "A question about the backup schedule."), (0, "The firing."), (0, "12:04 a.m.: the erase command."), (1, "The owner finds the drive empty.")],
        identified: "A remote login log.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let nurseDiversionV1 = SmallCases.make(
        key: "story.nurseDiversion",
        category: .drugs,
        headlines: ["Hospital Pharmacy Audit Finds Fentanyl Vials Refilled With Saline", "Night Nurse's Badge Opens the Narcotics Cabinet Most Often"],
        law: "prescriptionFraud",
        threshold: 10,
        spec: "Obtained fentanyl, a Schedule II controlled substance, by fraud, deceit, and misrepresentation, on {DATE}.",
        ages: 27...45,
        victim: false,
        summary: "A hospital pharmacy audit on {DATE} found fentanyl vials on {D}'s unit that were refilled with saline and resealed. {D}'s badge opened the narcotics cabinet more than any other nurse's, and {D} charted 140 partial doses as discarded with no second signature. {DL} says the cabinet was often left open on a busy ward.",
        state: [E(.forensic, 3, "Vial Testing", "Eleven sealed vials held saline."), E(.digital, 3, "Cabinet Log", "{D}'s badge opened the cabinet far more often than others."), E(.document, 3, "Waste Records", "140 partial doses without a witness."), E(.statement, 1, "Pharmacist", "The pharmacist says the vial seals were glued.")],
        defense: [E(.statement, 2, "Busy Ward", "{DL} says the cabinet stayed unlocked on busy nights.")],
        role: "Hospital pharmacy auditor",
        exam: [.direct("What did the vial testing show?", "\"Eleven sealed vials of fentanyl on {D}'s unit held only saline. The labels read fentanyl and the contents did not.\""), .direct("How were the vials altered?", "\"Refilled with saline and resealed. The pharmacist says the seals were glued rather than crimped.\""), .direct("Who opened the narcotics cabinet most?", "\"{DL}. {DL}'s badge opened the cabinet far more often than any other nurse on the unit.\""), .direct("What did the waste records show?", "\"140 partial doses charted as discarded without a second signature. Hospital policy requires a witness for every waste.\""), .direct("Why does a second signature matter?", "\"It prevents one person from claiming a drug was wasted when it was taken. Without it, the drug cannot be accounted for.\""), .direct("Did you find anything else of concern?", "\"Several wasted doses were charted on shifts when the patient's order did not call for any partial dose.\""), .cross("Did others have access to the cabinet?", "\"Yes. Every nurse on the unit had a badge that opened it, and some used a shared override.\""), .cross("Was the cabinet ever left open?", "\"At times. We found it ajar during one walk-through, and staff said it happened during rushes.\""), .cross("Could the high number of badge scans be explained by workload?", "\"Possibly. A nurse on a heavy surgical load would open it more, and {DL} had one.\""), .cross("Did you see {D} swap a vial?", "\"No. The audit looks at records and vials. No one observed a swap.\""), .cross("Did the defendant cooperate with the audit?", "\"Yes. {D.He} provided charts and answered questions, and did not resist.\"")],
        theory: ("{D} took painkillers meant for patients.", "Others had the same access."),
        allocution: "\"I have a problem and I need help.\"",
        truths: ("{DL} had been written up for charting errors before.", "The unit was short staffed and the cabinet was often left open."),
        defendant: [.direct("Did you swap vials?", "\"No. I did not swap, refill, or reseal any vial. I never put saline in a fentanyl vial.\""), .direct("Why so many partial doses?", "\"Heavy surgical load. Many of my patients needed partial doses, and I wasted what was left after each.\""), .direct("Why did no one sign as witness?", "\"Nobody was free. The ward was busy, and I could not find another nurse each time.\""), .direct("Why did your badge open the cabinet so often?", "\"Because I had the busiest assignment. I was pulling pain medication all shift for post-op patients.\""), .direct("Was the cabinet ever left open?", "\"Often, when it was busy. Nurses would step away and leave it ajar, and I closed it more than once.\""), .direct("What would you do differently?", "\"I would insist on a witness for every waste, even if it slowed me down. That was a mistake.\""), .cross("You charted 140 partial doses with no second signature, didn't you?", "\"I did. I know it is against policy, and I should have found a witness.\""), .cross("Eleven vials on your unit held saline, didn't they?", "\"Yes, on my unit. Many nurses worked there, and I did not do that.\""), .cross("Your badge opened the cabinet more than anyone's, didn't it?", "\"Yes, because of my assignment. It does not mean I took anything.\""), .cross("You were written up for charting errors before, weren't you?", "\"For paperwork, yes. Those were small mistakes, not drug diversion.\""), .cross("No one else is being audited, are they?", "\"I do not know. I only know what happened to me.\"")],
        openings: ("A hospital pharmacy audit found eleven fentanyl vials on {D}'s unit refilled with saline and resealed. {D}'s badge opened the narcotics cabinet more than any other nurse's, and {D} charted 140 partial doses as discarded with no second signature.", "The cabinet was often left open on a busy ward, and {D} had the heaviest surgical assignment. A nurse with the most work will have the most badge scans."),
        closings: ("Saline in fentanyl vials, the most cabinet scans on the unit, and 140 unwitnessed wastes in the chart. Every one of those records leads back to {D}.", "A busy ward, a cabinet often left open, and a nurse who skipped a signature in a rush. The State must prove {D} swapped the vials, and no one saw it."),
        timeline: [(-120, "Cabinet use rises."), (-30, "Waste records pile up."), (0, "The audit."), (10, "The pharmacy reports it.")],
        identified: "Vial tests and badge logs.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let beachTripV1 = SmallCases.make(
        key: "story.beachTrip",
        category: .family,
        headlines: ["Parent Misses Sunday Return; Child Found at Motel After Amber Alert", "Weekend Visit Turns Into Three-Day Search"],
        law: "transportChild",
        threshold: 7,
        spec: "Took {V}'s child out of North Carolina knowing it violated a custody order, on {DATE}.",
        ages: 27...44,
        victim: true,
        summary: "Under a custody order, {V} had primary custody and {D} had every other weekend. {D} picked the child up on Friday, {DATE}, and did not return on Sunday. {D}'s phone was off. On Tuesday police found them at a motel after an Amber Alert. {DL} says the child asked to stay and {D} lost track of the days.",
        state: [E(.document, 3, "Custody Order", "Return was due Sunday at 6 p.m."), E(.digital, 3, "Phone Records", "The phone was off until Tuesday."), E(.document, 2, "Motel Receipt", "Paid in cash for three nights.")],
        defense: [E(.statement, 1, "Child's Wish", "{DL} says the child begged for a few more days.")],
        role: "Custodial parent",
        exam: [.direct("What did the custody order say?", "\"I had primary custody, and {D} had every other weekend. Return was due Sunday at 6 p.m.\""), .direct("What happened that weekend?", "\"{D.He} picked up our child on Friday and did not return on Sunday. {D.his} phone was off, and I called many times.\""), .direct("Did {D} contact you?", "\"Never by phone. There was one text on Monday, and it did not say where they were or when they would be back.\""), .direct("What did you do?", "\"I called the police on Sunday night, then again Monday. By Tuesday they had issued an Amber Alert.\""), .direct("Where was the child found?", "\"At a motel, on Tuesday night. Police found them after the alert, and I met them at the station.\""), .direct("How did you feel those days?", "\"Sick with fear. I could not eat or sleep, and I imagined every bad thing. I just wanted our child home.\""), .cross("What was in the Monday text?", "\"A short message saying they were fine and would be back soon. It did not say a date.\""), .cross("Was the child safe when found?", "\"Yes. The child was fed, clean, and well when I saw them, though tired.\""), .cross("Has the defendant ever failed to return the child before?", "\"Not like this. {D.He} has sometimes returned late, by an hour or two.\""), .cross("Did the defendant have a reason to be upset with you?", "\"We have disagreed about custody. I am not saying {DL} is a bad parent.\""), .cross("Did the child talk about the trip?", "\"A little. The child said it was fun at the beach, and that {DL} let them stay up late.\"")],
        theory: ("{D} kept the child past the order and fled the state.", "A short vacation that ran long."),
        allocution: "\"I'm ready to take responsibility.\"",
        truths: ("{DL} paid cash and turned the phone off on purpose.", "The child cried to stay and {DL} planned to return Wednesday."),
        defendant: [.direct("Why was the phone off?", "\"The battery died. I forgot the charger, and I did not realize how long it had been off.\""), .direct("Why did you pay for the motel in cash?", "\"Cheaper. I did not have a card with room on it, and the motel offered a lower rate for cash.\""), .direct("Why did you leave the state?", "\"For a beach day. I wanted to give the child a fun trip, and the beach was a few hours away.\""), .direct("Why did Sunday pass without a return?", "\"I lost track. The child asked to stay one more day, and I told myself one more day would not hurt.\""), .direct("What did you do when you learned of the Amber Alert?", "\"I was shocked. I drove straight to the police, and I told them everything.\""), .direct("What do you want the court to know?", "\"I never meant to take the child away. I made a mistake with time, and I am sorry for the fear I caused.\""), .cross("The order said return by Sunday at 6, didn't it?", "\"Yes. I knew it, and I did not meet it. I should have called.\""), .cross("You sent one text on Monday, and nothing else, didn't you?", "\"Yes. I should have called {V} and told {V.him} where we were.\""), .cross("You paid cash for three nights at a motel, didn't you?", "\"I did. It was a cheaper room, and I did not want to use my card.\""), .cross("Your phone was off from Friday night until Tuesday, wasn't it?", "\"The battery died. I did not charge it, and I did not borrow another phone.\""), .cross("You took the child across state lines, didn't you?", "\"Yes. For a beach trip. I did not hide the child, and I did not run.\"")],
        openings: ("Under a custody order, {V} had primary custody and {D} had every other weekend. {D} picked up the child on Friday and did not return on Sunday, kept the phone off until Tuesday, and paid for a motel in cash before police found them after an Amber Alert.", "{D} took the child to the beach, lost track of the days, and let a dead phone battery compound a mistake. A late return is not a plan to take a child."),
        closings: ("A custody order with a Sunday deadline, a phone off for four days, a cash motel, and an Amber Alert. {D} knew when to return and did not.", "A dead battery, a beach trip, and a child who asked to stay another day. The State must prove {D} meant to keep the child from {V}, and {D} brought the child back."),
        timeline: [(-240, "The custody order is entered."), (0, "Friday pickup."), (2, "Sunday return missed."), (4, "Tuesday: the motel.")],
        identified: "An Amber Alert and a motel receipt.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let beachHouseV1 = SmallCases.make(
        key: "story.beachHouse",
        category: .property,
        headlines: ["Rental Cleaner Caught on Doorbell Camera Using a Key After Midnight", "Winter Break-In at Empty Beach House"],
        law: "burglary2",
        threshold: 8,
        spec: "Broke and entered at night the dwelling of {V} with the intent to commit larceny, on {DATE}.",
        ages: 23...45,
        victim: true,
        summary: "{V}'s rental house sits empty in winter. At 11:52 p.m. on {DATE} a doorbell camera recorded a person opening the side door with a key and carrying out two televisions, a laptop and jewelry. {D}'s company cleaned the house before the season and kept a key. {DL} says the key was copied before and anyone could have used it.",
        state: [E(.video, 3, "Doorbell Video", "A person in a dark jacket enters with a key and leaves with televisions."), E(.document, 3, "Key Log", "{D}'s company held the only key."), E(.digital, 2, "Pawn Listing", "A matching laptop was listed the next week.")],
        defense: [E(.statement, 1, "Copied Key", "{DL} says other cleaners also had copies.")],
        role: "Homeowner",
        exam: [.direct("What was taken from your rental house?", "\"Two televisions, a laptop, and jewelry. The house sits empty in winter, and I found out when I checked the cameras.\""), .direct("What did the doorbell camera show?", "\"At 11:52 p.m., a person in a dark jacket opened the side door with a key and carried out the televisions and other items.\""), .direct("Who had a key?", "\"{D}'s company cleaned the house before the season and kept a key. According to the key log, it was the only one on record.\""), .direct("Could you see a face on the video?", "\"No. The person kept the head down and wore a hood. I could only see a dark jacket.\""), .direct("What was listed afterward?", "\"A matching laptop was listed on a pawn listing the next week. I recognized it by a sticker on the lid.\""), .direct("How did you feel when you saw the video?", "\"Violated. The door was opened with a key, which meant someone I had trusted or someone who copied the key.\""), .cross("Were there other keys?", "\"Maybe. A neighbor and a former caretaker once had copies, and I never changed the lock.\""), .cross("Did {D} ever give you reason to distrust the company?", "\"No. They were reliable and careful, and I recommended them to friends.\""), .cross("Did you change the lock after the theft?", "\"Yes, the next day. I should have done it sooner.\""), .cross("Is the key log complete?", "\"It is what the company gave me. I did not verify every copy that ever existed.\""), .cross("Did you see the defendant near the house that night?", "\"No. I was not there, and I only know what the camera shows.\"")],
        theory: ("{D} used the cleaner's key to rob the house.", "A copied key and a stranger."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL}'s work schedule had nothing at that hour.", "{DL} gave back every key at the end of the season."),
        defendant: [.direct("Were you at the rental house that night?", "\"No. I was not there, and I did not take anything from that house.\""), .direct("Where were you?", "\"Home, with my family. We had dinner, watched television, and went to bed.\""), .direct("Can anyone confirm that?", "\"My family can. I have no one outside the family, and I know that is not the strongest.\""), .direct("You had the key, didn't you?", "\"Months ago, for the cleaning. I returned it at the end of the cleaning, or I thought I did.\""), .direct("Could the key have been copied?", "\"It could have. Keys get copied at hardware stores all the time, and I did not make a copy.\""), .direct("What do you want the homeowner to know?", "\"I am sorry for what happened. I did not do it, and I hope the real thief is caught.\""), .cross("The camera shows someone using a key, doesn't it?", "\"It does. The key could have been a copy, and I did not make one.\""), .cross("Your company held the only key on the log, didn't it?", "\"On the log, yes. The log is not a guarantee of who else had a copy.\""), .cross("A matching laptop was listed the next week, wasn't it?", "\"So the homeowner says. I did not list or sell any laptop.\""), .cross("You cleaned the house, so you knew it was empty, didn't you?", "\"I knew it was empty in winter, as did anyone who watched the house.\""), .cross("Your family is the only alibi you have, isn't it?", "\"Yes. That is the truth, and I cannot change it.\"")],
        openings: ("{V}'s rental house sits empty in winter. At 11:52 p.m. a doorbell camera recorded a person opening the side door with a key and carrying out two televisions, a laptop, and jewelry. {D}'s company cleaned the house and held the only key on record.", "The key could have been copied, no face is visible on the video, and {D} was home with family. A key on a log is not a thief in a dark jacket."),
        closings: ("A key used at the side door, the only key on the log held by {D}'s company, and a matching laptop listed the next week. The trail ends with {D}.", "A hooded figure, a key anyone could have copied, and a family alibi. The State cannot show who stood at that door."),
        timeline: [(-90, "Cleaning before the season."), (0, "11:52 p.m.: the door opens."), (1, "The owner finds the house stripped."), (8, "A laptop is listed.")],
        identified: "Doorbell video and a key log.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let horseStarvationV1 = SmallCases.make(
        key: "story.horseStarvation",
        category: .publicOrder,
        headlines: ["Six Beef Cattle Found Dying in Frozen Pasture With No Hay and an Iced-Over Trough", "Feed Store Shows No Purchases for Months"],
        law: "animalCruelty",
        threshold: 9,
        spec: "Intentionally deprived six cattle of necessary sustenance, causing unjustifiable pain and suffering.",
        ages: 40...70,
        victim: false,
        summary: "A neighbor photographed six beef cattle on {D}'s land for two months as they grew thinner in a pasture with no hay and an iced-over water trough. On {DATE}, animal control seized them. A veterinarian scored all six at the lowest possible body condition; two had to be euthanized. The feed store had no purchases from {D} since the fall. {DL} says {D.he} was hospitalized for three weeks and that a caretaker was supposed to feed them.",
        state: [E(.forensic, 3, "Veterinary Report", "All six at the lowest body condition; two euthanized."), E(.digital, 3, "Neighbor's Photos", "Two months of photos of thinning cattle."), E(.document, 3, "Feed Store Records", "No purchases since the fall."), E(.document, 1, "Animal Control Report", "No hay, ice on the trough.")],
        defense: [E(.document, 1, "Hospital Records", "{DL} admitted for three weeks."), E(.statement, 1, "Caretaker", "{DL} says a caretaker quit without notice.")],
        role: "Large animal veterinarian",
        exam: [.direct("What was the condition of the cattle?", "\"The lowest on the scale. All six scored the minimum body condition, with visible ribs, hips, and spine.\""), .direct("What did you find in the pasture?", "\"No hay and an iced-over water trough. The cattle had nothing to eat and nothing to drink but ice.\""), .direct("Did any of the cattle die?", "\"Two had to be euthanized. They were too weak to stand, and there was no recovery to hope for.\""), .direct("What did the neighbor's photos show?", "\"Two months of photographs of the same six cattle growing thinner each week, in a bare pasture.\""), .direct("What did the feed store records show?", "\"No purchases from {D} since the fall. We checked all the nearby feed suppliers and found nothing.\""), .direct("How long does it take for cattle to reach that condition?", "\"Weeks to months of inadequate feed. This was not a sudden change, and the photographs match that timeline.\""), .cross("Was {D} in the hospital?", "\"For three weeks, according to the records. {D.He} was admitted for a serious condition.\""), .cross("Did a caretaker have access?", "\"Reportedly. {DL} told us a caretaker was supposed to feed them, and I did not meet the caretaker.\""), .cross("Could the cattle have been fed from the defendant's own hay?", "\"Possibly. Feed store records do not show homegrown hay, and I found none in the barn.\""), .cross("Did the defendant cooperate with animal control?", "\"Yes. {D.He} answered questions and signed the seizure papers without argument.\""), .cross("Were the cattle otherwise healthy?", "\"Aside from starvation and some mild parasites, yes. They recovered well in our care.\"")],
        theory: ("{D} let cattle starve in a frozen pasture.", "A rancher whose caretaker quit."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} had not bought feed for two months before the hospital stay.", "{DL} had been warned by animal control a month before."),
        defendant: [.direct("Did you stop feeding them?", "\"No. I was in the hospital for three weeks, and I could not feed them or check on them.\""), .direct("Who fed them?", "\"A caretaker. I asked a person I trusted to feed and water the cattle while I was gone.\""), .direct("No feed since the fall, is that right?", "\"I used my own hay. I cut and baled hay in the summer, and I fed from that stack.\""), .direct("Why was there no hay in the pasture?", "\"The stack ran out, and I meant to buy more when I came home. The hospital stay got in the way.\""), .direct("What about the iced trough?", "\"It froze. I usually break the ice daily, and with me gone, no one did.\""), .direct("What do you want to say about the cattle?", "\"I am heartbroken. I loved those animals, and I trusted a person who did not do what I asked.\""), .cross("You were out of hay and had bought no feed since the fall, hadn't you?", "\"I ran short, and I should have bought more. I did not plan for the hospital.\""), .cross("The caretaker is not here, is the caretaker?", "\"No. I cannot find the name right now. I will find it.\""), .cross("Six cattle were at the lowest body condition, weren't they?", "\"Yes. I did not see them for three weeks, and I take responsibility.\""), .cross("Two had to be euthanized, didn't they?", "\"Yes. It breaks my heart. I would give anything to have prevented it.\""), .cross("You left cattle with no feed arrangement in writing, didn't you?", "\"I trusted a verbal one. I know that was foolish.\"")],
        openings: ("A neighbor photographed six beef cattle on {D}'s land for two months as they grew thinner in a pasture with no hay and an iced-over trough. A veterinarian scored all six at the lowest body condition, and two had to be euthanized.", "{D} was in the hospital for three weeks and a caretaker was supposed to feed the cattle. A serious illness and a failed arrangement are not intentional starvation."),
        closings: ("Two months of photographs, no hay, an iced trough, no feed purchases since the fall, and two cattle put down. Owners answer for their animals.", "A hospital stay, a caretaker who did not show, and hay from {D}'s own stack. The State must prove {D} knew the cattle were starving and chose not to feed them."),
        timeline: [(-90, "{D} buys the last feed."), (-60, "The neighbor begins photographing."), (-21, "{D} enters the hospital."), (0, "Animal control seizes the cattle."), (1, "The veterinarian's findings.")],
        identified: "A veterinary report.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let gasStationKidnappingV1 = SmallCases.make(
        key: "story.gasStationKidnapping",
        category: .robbery,
        headlines: ["Woman Forced Into Car at a Pump, Found Walking a Dark Road", "Camera at Pump Four Records the Grab"],
        law: "kidnapping1",
        threshold: 8,
        spec: "Unlawfully confined, restrained, and removed {V} from one place to another without consent for the purpose of terrorizing {V.him}, on {DATE}.",
        ages: 24...42,
        victim: true,
