        state: [E(.video, 3, "Pump Camera", "{D} grabs {V}'s arm and forces {V.him} into the passenger seat."), E(.forensic, 3, "Medical Report", "A swollen eye and bruising on the arm."), E(.digital, 2, "Phone Records", "{V}'s phone was found in {D}'s car.")],
        defense: [E(.statement, 1, "Willing Passenger", "{DL} says {V} climbed in and asked to leave.")],
        role: "Former partner",
        exam: [.direct("What happened at the gas pump?", "\"{D} grabbed my arm and pushed me into the passenger seat of a car. It was about 9:40 at night.\""), .direct("What was {D} doing as you were pushed in?", "\"Gripping my arm hard and saying to get in. I did not want to go, and I said so.\""), .direct("Where did you end up?", "\"On a dark road, miles away. {D.He} stopped the car, and we argued, and then I got out and walked.\""), .direct("What injuries did you have?", "\"A swollen eye and bruising on my arm. The medical report documents both.\""), .direct("What did the pump camera show?", "\"It shows {DL} grabbing my arm and forcing me into the passenger seat. It is clear and shows how it started.\""), .direct("What happened to your phone?", "\"It was found in {D.his} car. I did not have it with me when a deputy found me walking.\""), .cross("Did you scream?", "\"Not at first. I was in shock, and I did not want to make a scene at the station.\""), .cross("Had you argued before?", "\"Yes. We argued earlier, and it was about the breakup.\""), .cross("Did you get in the car on your own?", "\"No. I did not agree to get in. {D.He} pushed me in.\""), .cross("Did you see the defendant strike you?", "\"I do not remember a blow. I had a swollen eye by the time I was found, and I am not sure how it happened.\""), .cross("How long were you with the defendant?", "\"About two hours. It felt longer. I cannot give exact times.\"")],
