        state: [E(.document, 3, "Trooper Report", "Odor of alcohol, glassy eyes, and a failed walking test."), E(.statement, 3, "Drivers", "Two drivers swerved into a ditch."), E(.document, 2, "Refusal Form", "{DL} declined a breath test.")],
        defense: [E(.statement, 1, "Loose Steering", "{DL} says the tractor wanders in ruts.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What happened on the road that evening?", "\"At dusk, two drivers swerved into a ditch to avoid a tractor crossing the center line. I found the tractor a mile on.\""), .direct("What did you smell when you reached the driver?", "\"Alcohol. It was strong enough that I noticed it as soon as {D} rolled down the window of the tractor cab.\""), .direct("What else did you observe?", "\"Glassy eyes and slow speech. {D.He} said {D.he} was driving home from a cookout, and I took note of that.\""), .direct("What did you ask {D} to do?", "\"I asked {D.him} to step down and perform a walking test, heel to toe along a line. {D.He} swayed and stepped off the line.\""), .direct("What happened when you offered a breath test?", "\"{D.He} declined. I read the refusal form, and {D.he} acknowledged it and signed.\""), .direct("What did the two drivers tell you?", "\"Both said the tractor crossed the center line and forced them into the ditch. Neither was hurt, but both vehicles were stuck.\""), .cross("Was the road rough there?", "\"Some. There are patches and ruts on that stretch, and a tractor could bounce.\""), .cross("Can a tractor's steering be loose?", "\"Yes, especially an older one. Loose steering can make a tractor wander, and I did not inspect this one in detail.\""), .cross("How old is the defendant?", "\"In the later years of life. Age can affect balance and coordination, and I took that into account.\""), .cross("Did you see the defendant drink?", "\"No. I did not see any drinking. I smelled it and noted the signs.\""), .cross("Did the defendant cooperate otherwise?", "\"Yes. {D.He} was polite, stepped down when asked, and did not argue.\"")],
        theory: ("{D} drove a tractor while drunk.", "A loose steering box and a rutted road."),
