        defense: [E(.statement, 2, "Unaware", "{DL} says {D.he} did not feel the deputy.")],
        role: "Sheriff's deputy",
        exam: [.direct("Please explain your role as a sheriff's deputy.", "\"I patrol the county and make traffic stops every shift. I wear a body camera and I approach every stop with training in officer safety.\""), .direct("Why did you stop {D} on {DATE}?", "\"For a homemade license plate that read private traveler. That is not a valid plate, and the license on the vehicle was not legitimate.\""), .direct("What did you learn about the defendant's license?", "\"It had been revoked for two years. {D} refused to give a name and read from a laminated card claiming exemption from traffic law.\""), .direct("What did you do when the defendant refused to give a name?", "\"I reached into the window to take the keys. I wanted to prevent the car from leaving, and I told {D.him} to stop.\""), .direct("What happened next?", "\"{D.He} drove off while my arm was inside the window. I was dragged about forty feet before I broke free.\""), .direct("What injuries did you suffer?", "\"Road burns and a sprained shoulder. I was off work for several days, and my arm was sore for weeks.\""), .cross("Did the defendant say anything while you were reaching in?", "\"Yes. {DL} said to leave {DL} alone. {DL} also said {DL} would not stop.\""), .cross("Did the defendant accelerate hard?", "\"Yes. I felt the car accelerate. It did not brake for the forty feet, and I do not think {D.he} tried to slow down.\""), .cross("Could {D} have felt your arm?", "\"I think so. My arm was inside the window, and I was being pulled. But I cannot say what {D.he} felt.\""), .cross("Did the defendant threaten you?", "\"Not with a weapon. {D.He} just refused to cooperate. I did not see any weapon in the car.\""), .cross("Why do you think the defendant left?", "\"{D.He} says the stop was illegal. I do not know what {D.he} believed, and I cannot say whether {D.he} knew I was holding on.\"")],
