        timeline: [(-60, "{V} moves out."), (-20, "The tracker is placed."), (0, "The phone alert."), (2, "A mechanic finds it.")],
        identified: "Tracker records.",
        mood: .sympathetic,
        doctrines: ["burdenOfProof"])

    static let cyclistHitAndRunV1 = SmallCases.make(
        key: "story.cyclistHitAndRun",
        category: .traffic,
        headlines: ["Rider Killed by Car That Fled; Driver Blames a Deer", "Shattered Windshield Brought to Body Shop"],
        law: "hitAndRun",
        threshold: 2,
        spec: "Knowing or having reason to know the vehicle was involved in a crash causing death, failed to stop and remain at the scene, on {DATE}.",
        ages: 40...62,
        victim: true,
        summary: "At dusk on {DATE}, {V}, 29, was riding home on a country road when a car struck the bike from behind. {V} died in the ditch. The driver did not stop. Two days later a body shop called police about a silver sedan with a shattered windshield and a bent hood. {DL} says {D.he} hit a deer and never saw a rider.",
        state: [E(.forensic, 1, "Paint Transfer", "Silver paint on the bike frame."), E(.document, 1, "Body Shop Order", "A windshield and hood repair for {D}'s sedan.")],
        defense: [E(.statement, 1, "Deer", "{DL} says {D.he} hit a deer.")],
        role: "Highway Patrol crash investigator",
        exam: [.direct("What do you do as a Highway Patrol crash investigator?", "\"I investigate fatal and serious crashes. I examine paint, debris, and vehicle damage, and I work with labs and body shops to trace vehicles that leave the scene.\""), .direct("What happened at dusk on {DATE}?", "\"{V}, who was 29, was riding home on a country road when a car struck the bike from behind. {V} died in the ditch, and the driver did not stop.\""), .direct("What did you find on the bike?", "\"Silver paint on the frame. The lab found the paint matched a silver sedan, and that gave us a vehicle to look for.\""), .direct("How did {D}'s car come to your attention?", "\"Two days later a body shop called police about a silver sedan with a shattered windshield and a bent hood. The repair order lists {D}'s name.\""), .direct("What did the body shop order show?", "\"A windshield and hood repair for {DL}'s sedan. {DL} paid cash for the repair and gave a different story than the one {DL} later told.\""), .direct("What did you learn about the defendant's drive?", "\"{D.He} drove the same road each evening. That fits the time and place of the crash, and I noted it.\""), .cross("Was a deer found at the scene?", "\"No. We searched the road and the ditch and found no deer. I cannot say there was none.\""), .cross("Was there deer hair on the car?", "\"None. The lab did not find deer hair on {D.his} sedan. It did find paint transfer on the bike.\""), .cross("Could the defendant have hit a deer elsewhere?", "\"It is possible. {D.He} says {D.he} hit a deer and never saw a rider. I cannot disprove that, but the paint matches.\""), .cross("Did {D} say anything about why {D} did not stop?", "\"{D.He} said {D.he} was scared. I understand that, but it does not change the fact that {V} was left in the ditch.\""), .cross("Did anyone see the crash?", "\"No. No one saw it. We have the paint and the repair, and no witness saw the car strike the bike.\"")],
        theory: ("{D} killed a cyclist and drove away.", "A driver who hit a deer."),
        allocution: "\"I wasn't thinking about anyone else on the road.\"",
        truths: ("{DL} drove the same road each evening.", "{DL} paid cash for the repair and gave a different story."),
        defendant: [.direct("Tell us about your drive that evening.", "\"I drive that road home each evening. It was dusk, and I felt a hard impact. I thought it was a deer.\""), .direct("Why did you not stop?", "\"I was scared. I did not see a rider. I thought I had hit a deer, and I was afraid of what I would find.\""), .direct("How was your car damaged?", "\"The windshield shattered and the hood was bent. I took it to a body shop and paid cash to get it fixed.\""), .direct("Why did you tell the body shop a different story?", "\"I was nervous. I did not want trouble, and I made up something simpler, and I regret that now.\""), .direct("Did you know you had hit a person?", "\"No. I did not. I only learned it when deputies came to my door, and I was horrified.\""), .direct("How do you feel about what happened?", "\"Right now I feel sick. {V} died, and I did not stop. I think about it every night, and I am so sorry.\""), .cross("No deer was found, was it?", "\"No. They run. I know that is a weak explanation, but it is what I believed.\""), .cross("You paid cash for the repair, didn't you?", "\"Yes. It was cheaper. I did not think about how it would look afterward.\""), .cross("The paint on the bike matches your sedan, doesn't it?", "\"That is what they say. I did not know I had hit anyone. I only felt the impact.\""), .cross("You drive that road every evening, don't you?", "\"Yes. I know it was my road. I did not see a rider, and I would have stopped if I had.\""), .cross("You did not call anyone after the impact, did you?", "\"No. I did not. I was frightened, and I kept driving. I know that was wrong.\"")],
        openings: ("At dusk on {DATE}, {V}, 29, was riding home on a country road when a car struck the bike from behind. {V} died in the ditch, and the driver did not stop. Two days later, a body shop called police about a silver sedan with a shattered windshield and a bent hood.", "The defense will present a driver who thought it hit a deer, who never saw a rider, and who was scared. An accident that was not seen is not an intentional crime."),
        closings: ("Silver paint on the bike, a silver sedan with a shattered windshield, a cash repair, and a different story told to the body shop. {V} died in the ditch, and the driver did not stop.", "A deer in the dark, a driver who never saw a rider, and a fear that led to a cash repair. The State has not proved that {D} knew a person had been struck."),
        timeline: [(0, "Dusk: the crash."), (0, "The cyclist is found."), (2, "The body shop calls."), (3, "Arrest.")],
        identified: "Paint transfer and a body shop.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let hazingDeathV1 = SmallCases.make(
