        state: [E(.document, 3, "Military Records", "No service record for {D}."), E(.document, 3, "Charity Records", "$340,000 raised, $90,000 paid to {D}."), E(.video, 3, "Event Video", "{D} wearing medals and telling a battle story."), E(.statement, 2, "Donor", "{V} says {D} cited service as a reason to give.")],
        defense: [E(.statement, 2, "Mission", "{DL} says the housing projects were real.")],
        role: "Gold Star parent",
        exam: [.direct("Please tell us about your family and why you came to the event.", "\"My child died in military service. I attend Veterans Day events to honor my child, and I look for people who understand what service means.\""), .direct("What did {D} say at the event?", "\"{D} spoke in a uniform with medals and told a story of a battle overseas. {D.He} cited that service as a reason to give to the charity.\""), .direct("Why did you give to the charity?", "\"I believed {DL} had served and sacrificed. It touched me deeply, and I gave $10,000 because I thought it would honor soldiers like my child.\""), .direct("What did you learn later?", "\"A reporter asked for military records and found that {D.he} never served. There was no service record at all.\""), .direct("How did you feel when you learned that?", "\"Betrayed. I had trusted {D.him} with money meant to honor my child. It felt like {D.he} used my grief to raise funds.\""), .direct("What did the charity records show?", "\"$340,000 was raised, and $90,000 was paid to {D.him}. I did not know that when I gave.\""), .cross("Did the charity build housing?", "\"Some. The housing projects were real, and some families were helped. I do not dispute that.\""), .cross("Were you shown medals?", "\"Yes. {D.He} wore medals at the event. I did not check them, and I took them at face value.\""), .cross("Did the defendant claim a particular rank?", "\"I do not recall a rank. {D.He} told a battle story and wore medals, and that was enough for me to believe.\""), .cross("Did you ask what the money would be used for?", "\"I was told housing and memorials. I did not ask about salaries, and I did not know {D.he} was paid.\""), .cross("Would you have given if the defendant had not claimed service?", "\"I do not know. I gave because of the claim. I may have given less, or I may not have given at all.\"")],
        theory: ("{D} lied about service to raise money.", "A charity that did real work."),
