        timeline: [(-2190, "The first Veterans Day speech."), (-60, "The reporter's questions."), (0, "The records arrive."), (14, "The charge.")],
        identified: "Military records and charity records.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

