        defendant: [.direct("Tell the jury about living in the rental house.", "\"I lease the house and share it with two roommates. We split the rent, and we share the kitchen and the freezer.\""), .direct("Was the tub yours?", "\"No. I do not eat protein powder. A roommate kept the tub, and I never opened it.\""), .direct("Why did you get a new freezer?", "\"The old one broke. I ordered a new one, and it was delivered the week before the search. It had nothing to do with drugs.\""), .direct("Do you know about the capsules and the scale?", "\"I saw them for the first time during the search. They were not mine, and I do not know who brought them.\""), .direct("What about the phone in the kitchen?", "\"It was not mine. I do not know whose it was. I did not read the messages, and I do not know what they meant.\""), .direct("How has this affected you?", "\"I would say I feel confused and scared. I lease the house, but I did not keep fentanyl there, and I do not know why a roommate blames me.\""), .cross("The lease is only in your name, isn't it?", "\"Yes. I signed it. I know that makes me responsible for the house, but not for what a roommate keeps.\""), .cross("A roommate says the tub was yours, doesn't the roommate?", "\"Yes. The roommate is wrong. I do not know why the roommate says that.\""), .cross("The messages discuss the powder and prices, don't they?", "\"I am told so. They are on a phone that is not mine, and I did not write them.\""), .cross("You had a new freezer delivered the week before, didn't you?", "\"Yes. The old one broke. I know the timing looks odd, but that is what happened.\""), .cross("The scale and capsules were in your house, weren't they?", "\"Yes. They were in the house. I do not know who put them there, and I did not use them.\"")],
        openings: ("Deputies searched a rental house on {DATE} and found 30 grams of fentanyl in a protein powder tub in the freezer, along with a scale and 200 empty capsules. The lease was in {D}'s name, and text messages on a phone in the kitchen discussed the powder and prices.", "The defense will present a shared house with three people, a tub that a roommate kept, and a phone that was not {D}'s. Being the person on the lease is not the same as owning what is in the freezer."),
        closings: ("Thirty grams of fentanyl in a tub in the freezer, a scale, 200 capsules, a lease in {D}'s name, and a new freezer delivered the week before. The house was {D}'s, and so was the responsibility.", "A shared house, a tub that a roommate kept, and a phone that was not {D}'s. The State has not proved that {D} knew the fentanyl was in the freezer."),
        timeline: [(-7, "A freezer is delivered."), (0, "6 a.m.: the warrant is served."), (0, "The tub is found."), (0, "The phone messages are read."), (3, "The lab confirms fentanyl.")],
        identified: "A search warrant.",
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let neighborStalkingV1 = SmallCases.make(
        key: "story.neighborStalking",
        category: .family,
        headlines: ["Car Outside Home Every Night for Six Weeks, Gifts Left on the Windshield", "Gym Sign-In Sheets Show Same Visitor Beside Resident"],
        law: "stalking",
        threshold: 6,
        spec: "Willfully harassed {V} on more than one occasion without legal purpose, on {DATE}.",
        ages: 28...65,
        victim: true,
        summary: "For six weeks ending {DATE}, {V} saw a gray car parked outside {V.his} house most evenings and found notes under the windshield wiper. {V} kept a log and photographed the plate. The car belonged to {D}. A gym sign-in sheet showed {D} arriving minutes after {V} on eleven days. {DL} says {D.he} works nearby and the gym is on the way home.",
        state: [E(.document, 3, "Resident's Log", "Thirty-one evenings noted with times."), E(.physical, 2, "Notes", "Four handwritten notes under the windshield wiper."), E(.document, 2, "Gym Sign-In", "{D} signs in minutes after {V} on eleven days."), E(.digital, 1, "Plate Photos", "The car's plate photographed on nine evenings.")],
        defense: [E(.statement, 1, "On the Way Home", "{DL} says the gym is near {D.his} work."), E(.statement, 1, "Gifts", "{DL} says the notes were friendly.")],
        role: "Resident",
        exam: [.direct("Please describe your home and your evenings.", "\"I live on a quiet street, and I usually come home around the same time each evening. I notice what is parked outside, and I noticed a gray car.\""), .direct("What did you notice about the gray car?", "\"It was parked outside my house most evenings for six weeks. I kept a log, and I noted 31 evenings with times.\""), .direct("What did you find on your windshield wiper?", "\"Notes. There were four handwritten notes. At first they were friendly, and then they became insistent.\""), .direct("What did you do about it?", "\"I photographed the plate on nine evenings and gave the log and photos to a deputy. The car belonged to {D}.\""), .direct("What did the gym sign-in sheets show?", "\"{D.He} signed in minutes after me on eleven days. I go to that gym regularly, and I started to see {D.him} there.\""), .direct("How did all of this make you feel?", "\"Uneasy and watched. I changed my routines and checked outside before leaving. I did not feel safe at home or at the gym.\""), .cross("Did {D} ever speak to you?", "\"Sometimes at the gym. {D.He} said hello, and I answered politely. I did not want a conversation, and I did not know why {D.he} was always there.\""), .cross("Were the notes threatening?", "\"No. They were friendly at first, then insistent. They did not contain threats, but I did not like them.\""), .cross("Does the defendant work near the gym?", "\"{D.He} says so. I do not know where {D.he} works. I only know {D.he} came after me on eleven days.\""), .cross("Did you ask the defendant to stop?", "\"Not directly. I did not know how. I told a deputy, and I did not speak to {DL} about it.\""), .cross("Could the evenings be a coincidence?", "\"Some might be. But 31 evenings in six weeks is not something I can call a coincidence.\"")],
        theory: ("{D} followed and watched {V} for six weeks.", "A neighbor whose routes crossed {V}'s."),
        allocution: "\"I'm sorry, and I mean it.\"",
        truths: ("{DL} had asked a coworker which gym {V} used.", "{DL} parked at the end of the street for at least an hour each night."),
        defendant: [.direct("Describe your evenings near {V}'s street for the jury.", "\"I parked outside {V}'s house sometimes. I like the quiet. I sat there to think after work, and I did not mean any harm.\""), .direct("Why did you leave notes?", "\"They were friendly. I wanted to say hello. I did not think they would be taken as anything but kind.\""), .direct("Why were you at the same gym as {V}?", "\"It is near my work and on my way home. I use that gym because it is convenient, and I did not go to see {V}.\""), .direct("Why did you ask a coworker which gym {V} used?", "\"I was curious. I wanted to know where {V} went. I know that sounds strange, and I should not have asked.\""), .direct("Why did you park for an hour each night?", "\"I like the quiet. It was a good place to sit. I did not know it would make {V} uncomfortable.\""), .direct("How has this affected you?", "\"Honestly, I feel embarrassed. I did not mean to scare {V}. I did not realize how it looked, and I would stop if I had known.\""), .cross("You asked a coworker which gym {V} used, didn't you?", "\"Yes. I was curious. I know it looks bad, and I should not have asked.\""), .cross("You parked at the end of the street for at least an hour each night, didn't you?", "\"Yes. I did. I like the quiet. I know it was close to {V}'s house.\""), .cross("You signed in minutes after {V} on eleven days, didn't you?", "\"Yes. The sheets show that. I did not plan it, but I know it happened often.\""), .cross("You left four notes on {V}'s car, didn't you?", "\"Yes. I did. They were friendly, but I understand that {V} did not want them.\""), .cross("{V} never asked you to leave notes, did {V}?", "\"No. {V} did not. I should have stopped when I did not get a reply.\"")],
        openings: ("For six weeks ending {DATE}, {V} saw a gray car parked outside the house most evenings and found notes under the windshield wiper. {V} kept a log and photographed the plate, and a gym sign-in sheet showed {D} arriving minutes after {V} on eleven days.", "The defense will present a neighbor whose route crosses {V}'s, a gym on the way home, and notes that were meant to be friendly. {D} did not mean to scare anyone."),
        closings: ("Thirty-one evenings in a log, four notes, plate photos on nine evenings, and a sign-in sheet that shows {D} behind {V} on eleven days. The pattern is plain.", "Friendly notes, a shared route, and a quiet place to park. The State has not proved that {D} meant to follow and frighten {V}."),
        timeline: [(-42, "The car first appears."), (-28, "The first note."), (-7, "{V} starts a log."), (0, "{V} reports it."), (1, "A deputy checks the plate.")],
        identified: "A resident's log.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let chopShopV1 = SmallCases.make(
        key: "story.chopShop",
        category: .property,
        headlines: ["GPS Tracker in Stolen Truck Pings Inside Body Shop", "Parts of Dozens of Pickups Found in Back Lot"],
        law: "possStolen",
        threshold: 10,
        spec: "Possessed a stolen pickup belonging to {V}, knowing it had been stolen, on {DATE}.",
        ages: 38...50,
        victim: true,
        summary: "On {DATE}, after a GPS tracker in {V}'s stolen pickup pinged inside a body shop, detectives got a warrant. Inside they found {V}'s truck half-stripped on a lift and, in the back lot, cabs, frames and engines from about thirty pickups. {D} ran the shop. {DL} says {D.he} bought parts at auction and never checked titles.",
        state: [E(.physical, 3, "Stolen Truck", "{V}'s truck half-stripped on a lift."), E(.digital, 3, "GPS Log", "The tracker pings inside the shop."), E(.document, 3, "Parts Inventory", "Parts from about thirty pickups."), E(.document, 2, "Titles", "No titles for most parts.")],
        defense: [E(.statement, 2, "Auction Parts", "{DL} says the parts were bought at auctions.")],
        role: "Auto theft detective",
        exam: [.direct("How would you describe your job as an auto theft detective?", "\"I investigate stolen vehicles and parts rings. I trace GPS signals, serve warrants, and inventory parts to match them with stolen trucks.\""), .direct("How did your investigation begin on {DATE}?", "\"A GPS tracker in {V}'s stolen pickup pinged inside a body shop. I used the ping to get a warrant.\""), .direct("What did you find inside the shop?", "\"{V}'s truck half-stripped on a lift. {D} ran the shop, and the truck was in the work area.\""), .direct("What did you find in the back lot?", "\"Cabs, frames, and engines from about thirty pickups. The inventory lists parts from about thirty trucks, and most had no titles.\""), .direct("What did the GPS log show?", "\"It shows the tracker pinging inside the shop. The log matches the time when the truck was taken and when it arrived.\""), .direct("What did you learn about {D}'s past?", "\"{D.He} had been fined once for the same thing. I noted that in my report and reviewed the prior case.\""), .cross("Did the defendant have titles for any parts?", "\"For some. Most parts had no titles. A shop that buys parts at auction should have titles for them.\""), .cross("Was the defendant present during the search?", "\"Yes. {D.He} was at the shop, and {D.he} cooperated. {D.He} said the parts were bought at auctions.\""), .cross("Do auctions sell parts without titles?", "\"Sometimes. But the auction would have records, and {DL} could not produce them for most of the parts.\""), .cross("Could {V}'s truck have been bought in good faith?", "\"That is what {DL} says. I could not find a record of a sale or an auction for that truck.\""), .cross("Did you see the defendant take the truck apart?", "\"No. I did not see it. I found it half-stripped on a lift, and I do not know who started the work.\"")],
        theory: ("{D} ran a chop shop.", "A shop owner buying parts in good faith."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} had no titles for most of the parts.", "{DL} had been fined once for the same thing."),
        defendant: [.direct("Tell the jury about your body shop.", "\"I run a body shop that fixes trucks and sells used parts. It is a big shop with a lot of inventory, and I have been in this business for years.\""), .direct("Where did {V}'s truck come from?", "\"An auction. I bought it with a lot of other vehicles. I did not know it was stolen, and I did not steal it.\""), .direct("Why were there no titles for most parts?", "\"Paperwork lags. Titles come later, and I do not always check them when I buy. It was a mistake, and I know it.\""), .direct("Why did you have parts from about thirty pickups?", "\"It is a big shop. I buy parts at auctions and from other shops. I do not know where each came from.\""), .direct("What were you fined for before?", "\"For the same issue with titles. I paid the fine, and I told myself I would fix it. I did not fix it as I should have.\""), .direct("Looking back, how do you feel about what happened?", "\"Lately I feel awful. I did not mean to buy a stolen truck. I will do a better job checking titles from now on.\""), .cross("You did not check titles on most of your parts, did you?", "\"No. I did not. I know I should have, and I understand why that looks bad.\""), .cross("A GPS tracker pinged inside your shop, didn't it?", "\"Yes. It did. I did not know the tracker was there, and I do not know how it got into the truck.\""), .cross("You were fined once for the same thing, weren't you?", "\"Yes. I paid it. I should have changed how I work, and I did not.\""), .cross("You cannot show an auction record for {V}'s truck, can you?", "\"Not with me. I thought I had paperwork, but it did not turn up. I know how that sounds.\""), .cross("You had been fined before for having parts without titles, hadn't you?", "\"Yes, once. I paid the fine and changed how I kept records. I thought I had done enough, and clearly I had not.\"")],
        openings: ("After a GPS tracker in {V}'s stolen pickup pinged inside a body shop on {DATE}, detectives got a warrant and found {V}'s truck half-stripped on a lift. In the back lot were cabs, frames, and engines from about thirty pickups, and {D} ran the shop.", "The defense will present a shop owner who bought parts at auction in good faith and paperwork that lagged. A messy business is not the same as a chop shop."),
        closings: ("A stolen truck half-stripped on a lift, a tracker that pinged inside the shop, parts from thirty pickups, and almost no titles. {D} had been fined once for the same thing.", "A big shop with auction parts and paperwork that lagged. The State has not proved that {D} knew the truck was stolen or ran a chop shop."),
        timeline: [(-7, "The truck is stolen."), (0, "The tracker pings."), (1, "The warrant."), (2, "The inventory.")],
        identified: "A GPS tracker.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof", "searchSeizure"],
        genders: ["D": .male])

    static let moonshineExplosionV1 = SmallCases.make(
        key: "story.moonshineExplosion",
        category: .publicOrder,
        headlines: ["Barn Fire Kills Teen Who Was Paid to Watch Illegal Still", "Propane Explosion Throws Roof Off Barn"],
