        state: [E(.video, 3, "Counter Camera", "A masked person with a black pistol."), E(.video, 3, "Drugstore Camera", "{D} in the same sweatshirt two days later."), E(.document, 3, "Inventory", "About 400 oxycodone pills missing.")],
        defense: [E(.statement, 2, "Thrift Shop", "{DL} says the sweatshirt came from a thrift bin.")],
        role: "Pharmacist",
        exam: [.direct("What do you do as a pharmacist?", "\"I am the pharmacist on duty most evenings. I fill prescriptions, manage controlled substances, and keep the pharmacy secure.\""), .direct("What happened on {DATE}?", "\"A person in a hooded sweatshirt and a surgical mask walked up to the counter, lifted a black pistol from a jacket pocket, and told me to empty the oxycodone drawer.\""), .direct("What did you do?", "\"I followed the order. I emptied the drawer and handed over about 400 pills. I was terrified.\""), .direct("How did the person leave?", "\"On foot, out the front door. I pressed the alarm and called 911 as soon as the door closed.\""), .direct("What could you see of the face?", "\"Only the eyes, above the mask. I could see that the person was staring at me, and I could not see anything else.\""), .direct("Do you know {D} from before?", "\"{D} had been refused a refill at that counter earlier. I recognized the name when deputies said it, but I did not see the face.\""), .cross("Was the gun real?", "\"I think so. It looked like a real black pistol. I did not see it fired, and I did not touch it.\""), .cross("Could you identify the person?", "\"No. The mask and hood covered most of the face. I cannot say it was {DL} based on what I saw.\""), .cross("Was the sweatshirt unusual?", "\"No. It is a common hooded sweatshirt. I saw it on camera, and the drugstore camera shows {DL} in the same style.\""), .cross("How many pills were taken?", "\"About 400 oxycodone pills. We counted the inventory afterward, and the missing count matches.\""), .cross("Did the person speak?", "\"Only to give the order. The voice was low and muffled by the mask. I could not tell anything about the person from it.\"")],
        theory: ("{D} robbed a pharmacy at gunpoint.", "A buyer of a common sweatshirt."),
