        defendant: [.direct("What can you tell us about your history with the pharmacy?", "\"I was a customer there, and I had been refused a refill once. It was a hard time for me. I was upset, but I moved on.\""), .direct("Did you rob the pharmacy?", "\"No. I did not. I have never robbed anyone, and I would not point a gun at a pharmacist.\""), .direct("Where did you get the sweatshirt?", "\"From a thrift bin. It is a common sweatshirt. I donated it or lost it, and I wore it for a while.\""), .direct("Why was a pistol in your car?", "\"It is licensed. I keep it for protection. It is not the pistol on camera, and I did not use it for anything.\""), .direct("Why did the drugstore camera show you in the sweatshirt two days later?", "\"I was shopping. I wore the sweatshirt because it was clean. It did not seem important to me.\""), .direct("Looking back, how do you feel about being accused?", "\"Scared, more than anything. I did not rob anyone, and I do not understand how a sweatshirt can be enough.\""), .cross("You had been refused a refill at that counter, hadn't you?", "\"Yes. It was old news. I was not angry enough to rob anyone.\""), .cross("A pistol matching the one shown was in your car, wasn't it?", "\"A black pistol, yes. It is licensed, and many pistols look alike. I did not use it in a robbery.\""), .cross("You wore the same sweatshirt two days later, didn't you?", "\"Yes. It is a common sweatshirt. I did not think it would matter.\""), .cross("About 400 pills were taken, weren't they?", "\"That is what I am told. I do not have them, and I did not take them.\""), .cross("You cannot prove where you were during the robbery, can you?", "\"I was home. No one can confirm it. I know that is a weakness, and it is the truth.\"")],
        openings: ("On {DATE}, a person in a hooded sweatshirt and a surgical mask lifted a black pistol at the pharmacy counter and told {V}, the pharmacist, to empty the oxycodone drawer. About 400 pills were taken, and two days later {D} appeared on a drugstore camera in the same sweatshirt.", "The defense will present a common sweatshirt from a thrift bin, a licensed pistol, and a person who has never robbed anyone. A matching sweatshirt is not a robbery."),
        closings: ("A masked person with a black pistol, about 400 oxycodone pills gone, {D} in the same sweatshirt two days later, a refused refill, and a matching pistol in {D}'s car. The evidence ties {D} to the robbery.", "A common sweatshirt, a licensed pistol, and a refill that was refused long ago. The State has not proved that {D} was the masked person at the counter."),
        timeline: [(-14, "A refill is refused."), (0, "The robbery."), (2, "The drugstore camera."), (3, "A search.")],
        identified: "Two cameras.",
